import csv
import json
import os
from datetime import datetime
from urllib.parse import urlparse


def existing_identity(value):
    return value

def existing_strip_v(value):
    return value.removeprefix("v")

def existing_parse_bool(value):
    return json.loads(value)

def existing_join_path(base, child):
    return os.path.join(base, child)

def existing_iso_date(value):
    return datetime.fromisoformat(value).date().isoformat()

def existing_clamp(value, low, high):
    return max(low, min(high, value))

def existing_first_nonempty(values):
    return next((value for value in values if value.strip()), None)

def existing_split_host(value):
    parsed = urlparse(value)
    return parsed.hostname

def existing_env_default(mapping, name, default):
    return mapping.get(name, default)

def existing_csv_column(text, column):
    return [row[column] for row in csv.DictReader(text.splitlines()) if row.get(column)]

def existing_dedupe(values):
    return list(dict.fromkeys(values))

